class RWLock:
    def __init__(self):
        self.c = threading.Condition(); self.readers = 0; self.writing = False; self.waiting_w = 0
    def acquire_read(self):
        with self.c:
            while self.writing or self.waiting_w: self.c.wait()
            self.readers += 1
    def release_read(self):
        with self.c:
            self.readers -= 1
            if self.readers == 0: self.c.notify_all()
    def acquire_write(self):
        with self.c:
            self.waiting_w += 1
            while self.writing or self.readers: self.c.wait()
            self.waiting_w -= 1; self.writing = True
    def release_write(self):
        with self.c:
            self.writing = False; self.c.notify_all()

